import{_ as s,a0 as r,w as l,s as m,ao as i,I as n,a1 as o,A as a,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何使用 pv 命令監控 linux 命令的執行進度 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 pv 命令監控 linux 命令的執行進度 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 pv 命令監控 linux 命令的執行進度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 pv 命令監控 linux 命令的執行進度 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151109 How to Monitor the Progress of a Linux Command Line Operation Using PV Command","title":"如何使用 pv 命令監控 linux 命令的執行進度","tag":"201512","desc":""},"relativePath":"201512/20151109 How to Monitor the Progress of a Linux Command Line Operation Using PV Command.md","filePath":"[post].md"}'),d={name:"201512/20151109 How to Monitor the Progress of a Linux Command Line Operation Using PV Command.md"};function u(f,e,v,g,h,x){const p=r("Link");return l(),m("div",null,[e[18]||(e[18]=i('<h1 id="如何使用-pv-命令監控-linux-命令的執行進度" tabindex="-1">如何使用 pv 命令監控 linux 命令的執行進度 <a class="header-anchor" href="#如何使用-pv-命令監控-linux-命令的執行進度" aria-label="Permalink to “如何使用 pv 命令監控 linux 命令的執行進度”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/pv-featured-1.jpg" alt=""></p><p>如果你是一個 linux 系統管理員，那麼毫無疑問你必須花費大量的工作時間在命令列上：安裝和卸載軟件，監視系統狀態，複製、移動、刪除文件，查錯，等等。很多時候都是你輸入一個命令，然後等待很長時間直到執行完成。也有的時候你執行的命令掛起了，而你只能猜測命令執行的實際情況。</p><p>通常 linux 命令不提供和進度相關的信息，而這些信息特別重要，尤其當你只有有限的時間時。然而這並不意味着你是無助的——現在有一個命令，pv，它會顯示當前在命令列執行的命令的進度信息。在本文我們會討論它並用幾個簡單的例子説明其特性。</p><h3 id="pv-命令" tabindex="-1">PV 命令 <a class="header-anchor" href="#pv-命令" aria-label="Permalink to “PV 命令”">​</a></h3>',5)),n("p",null,[o(p,{href:"http://linux.die.net/man/1/pv"},{default:a(()=>[...e[0]||(e[0]=[t("PV",-1)])]),_:1}),e[1]||(e[1]=t(" 由Andrew Wood 開發，是 Pipe Viewer 的簡稱，意思是通過管道顯示數據處理進度的信息。這些信息包括已經耗費的時間，完成的百分比（通過進度條顯示），當前的速度，全部傳輸的數據，以及估計剩餘的時間。",-1))]),e[19]||(e[19]=i(`<blockquote><p>&quot;要使用 PV，需要配合合適的選項，把它放置在兩個進程之間的管道。命令的標準輸入將會通過標準輸出傳進來的，而進度會被輸出到標準錯誤輸出。”</p></blockquote><p>上述解釋來自該命令的幫助頁。</p><h3 id="下載和安裝" tabindex="-1">下載和安裝 <a class="header-anchor" href="#下載和安裝" aria-label="Permalink to “下載和安裝”">​</a></h3><p>Debian 系的操作系統，如 Ubuntu，可以簡單的使用下面的命令安裝 PV：</p><pre><code>sudo apt-get install pv
</code></pre><p>如果你使用了其他發行版本，你可以使用各自的包管理軟件在你的系統上安裝 PV。一旦 PV 安裝好了你就可以在各種場合使用它（詳見下文）。需要注意的是下面所有例子都使用的是 pv 1.2.0。</p><h3 id="特性和用法" tabindex="-1">特性和用法 <a class="header-anchor" href="#特性和用法" aria-label="Permalink to “特性和用法”">​</a></h3><p>我們（在 linux 上使用命令列的用户）的大多數使用場景都會用到的命令是從一個 USB 驅動器拷貝電影文件到你的電腦。如果你使用 cp 來完成上面的任務，你會什麼情況都不清楚，直到整個複製過程結束或者出錯。</p><p>然而pv 命令在這種情景下很有幫助。比如：</p><pre><code>pv /media/himanshu/1AC2-A8E3/fNf.mkv &gt; ./Desktop/fnf.mkv
</code></pre><p>輸出如下：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-copy.png" alt="pv-copy"></p><p>所以，如你所見，這個命令顯示了很多和操作有關的有用信息，包括已經傳輸了的數據量，花費的時間，傳輸速率，進度條，進度的百分比，以及剩餘的時間。</p><p><code>pv</code> 命令提供了多種顯示選項開關。比如，你可以使用<code>-p</code> 來顯示百分比，<code>-t</code> 來顯示時間，<code>-r</code> 表示傳輸速率，<code>-e</code> 代表eta（LCTT 譯註：估計剩餘的時間）。好事是你不必記住某一個選項，因為默認這幾個選項都是啓用的。但是，如果你只要其中某一個信息，那麼可以通過控制這幾個選項來完成任務。</p><p>這裏還有一個<code>-n</code> 選項來允許 pv 命令顯示整數百分比，在標準錯誤輸出上每行顯示一個數字，用來替代通常的可視進度條。下面是一個例子：</p><pre><code>pv -n /media/himanshu/1AC2-A8E3/fNf.mkv &gt; ./Desktop/fnf.mkv
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-numeric.png" alt="pv-numeric"></p>`,17)),n("p",null,[e[3]||(e[3]=t("這個特殊的選項非常合適某些情境下的需求，如你想把用管道把輸出傳給",-1)),o(p,{href:"http://linux.die.net/man/1/dialog"},{default:a(()=>[...e[2]||(e[2]=[t("dialog",-1)])]),_:1}),e[4]||(e[4]=t(" 命令。",-1))]),e[20]||(e[20]=i(`<p>接下來還有一個命令列選項，<code>-L</code> 可以讓你修改 pv 命令的傳輸速率。舉個例子，使用 -L 選項來限制傳輸速率為2MB/s。</p><pre><code>pv -L 2m /media/himanshu/1AC2-A8E3/fNf.mkv &gt; ./Desktop/fnf.mkv
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-ratelimit.png" alt="pv-ratelimit"></p><p>如上圖所見，數據傳輸速度按照我們的要求被限制了。</p><p>另一個pv 可以幫上忙的情景是壓縮文件。這裏有一個例子可以向你解釋如何與壓縮軟件Gzip 一起工作。</p><pre><code>pv /media/himanshu/1AC2-A8E3/fnf.mkv | gzip &gt; ./Desktop/fnf.log.gz
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-gzip.png" alt="pv-gzip"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>如上所述，pv 是一個非常有用的小工具，它可以在命令沒有按照預期執行的情況下幫你節省你寶貴的時間。而且這些顯示的信息還可以用在 shell 腳本里。我強烈的推薦你使用這個命令，它值得你一試。</p><hr>`,10)),n("p",null,[e[6]||(e[6]=t("via: ",-1)),o(p,{href:"https://www.maketecheasier.com/monitor-progress-linux-command-line-operation/"},{default:a(()=>[...e[5]||(e[5]=[t("https://www.maketecheasier.com/monitor-progress-linux-command-line-operation/",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("作者：",-1)),o(p,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:a(()=>[...e[7]||(e[7]=[t("Himanshu Arora",-1)])]),_:1}),e[11]||(e[11]=t(" 譯者：",-1)),o(p,{href:"https://github.com/oska874"},{default:a(()=>[...e[8]||(e[8]=[t("ezio",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:a(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創編譯，",-1)),o(p,{href:"https://linux.cn/"},{default:a(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const k=s(d,[["render",u]]);export{C as __pageData,k as default};
